/bin/bash -lc "node - <<'NODE'
const http = require('http');
function getJson(url){return new Promise((res,rej)=>http.get(url,r=>{let d='';r.on('data',c=>d+=c);r.on('end',()=>res(JSON.parse(d)));}).on('error',rej));}
async function cdp(wsUrl){
 const ws = new WebSocket(wsUrl); let id=0; const pending=new Map();
 ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.id&&pending.has(m.id)){pending.get(m.id).resolve(m); pending.delete(m.id)}};
 await new Promise((res,rej)=>{ws.onopen=res; ws.onerror=rej});
 const send=(method,params={})=>new Promise((resolve,reject)=>{const i=++id; pending.set(i,{resolve,reject}); ws.send(JSON.stringify({id:i,method,params}));});
 return {send,close:()=>ws.close()};
}
(async()=>{
 const pages=await getJson('http://127.0.0.1:1337/json');
 const page=pages.find(p=>p.url==='https://www.nba.com/') || pages[0];
 const client=await cdp(page.webSocketDebuggerUrl);
 await client.send('Page.enable');
 await client.send('Runtime.enable');
 await client.send('Page.navigate',{url:'https://store.nba.com/nike-women-jerseys/br-1873%2Bga-79%2Bd-4550407494%2Bz-991-1909762557?priceRange=60-_&pageSize=72&sortOption=TopSellers'});
 await new Promise(r=>setTimeout(r,5000));
 const info=await client.send('Runtime.evaluate',{expression:'({href:location.href,title:document.title,body:document.body.innerText.slice(0,2000)})',returnByValue:true});
 console.log(JSON.stringify(info.result.result.value,null,2));
 client.close();
})();
NODE"

